System.register("chunks:///_virtual/content.ts",["cc"],(function(e){var t;return{setters:[function(e){t=e.cclegacy}],execute:function(){t._RF.push({},"cb5e211YuVGILKbhqY7618B","content",void 0);e("BEADS",[{name:"月光珍珠",short:"珍珠",color:"#eadfc9",dark:"#a48c73",shape:"circle"},{name:"蔷薇红晶",short:"红心",color:"#cf8d91",dark:"#9e6368",shape:"heart"},{name:"雾蓝水晶",short:"蓝晶",color:"#a2c2d1",dark:"#628caa",shape:"diamond"},{name:"森绿玉珠",short:"绿玉",color:"#a9b98c",dark:"#74845d",shape:"leaf"},{name:"蜜金星珠",short:"金星",color:"#e3c37c",dark:"#ae8d47",shape:"star"},{name:"紫雾花珠",short:"花珠",color:"#c3accb",dark:"#927a9e",shape:"flower"}]),e("ORDERS",[{id:"daisy",name:"给奶奶的一朵花",customer:"林阿姨",occasion:"一份迟来的生日礼物",text:"妈妈总说不用花钱。我想送她一点，属于她自己的漂亮。",main:0,accent:3,mainNeed:6,accentNeed:3,charm:"daisy",reward:180,rep:10,palette:[0,3,0,0,3,0,0,3,0,0,4,0]},{id:"sea",name:"把海风戴在手上",customer:"花店小满",occasion:"送给勇敢出发的自己",text:"这是我第一次独自去旅行。想要蓝色，像天刚亮时的海。",main:2,accent:0,mainNeed:6,accentNeed:3,charm:"moon",reward:220,rep:15,palette:[2,0,2,2,0,2,2,0,2,2,4,2]},{id:"rose",name:"温柔也有力量",customer:"许老师",occasion:"给即将毕业的学生",text:"她被别人说太安静了。我想告诉她，安静也可以很有力量。",main:1,accent:0,mainNeed:6,accentNeed:3,charm:"heart",reward:260,rep:20,palette:[1,0,1,1,0,1,1,0,1,1,4,1]},{id:"forest",name:"留住一座小森林",customer:"林阿姨",occasion:"纪念重新开张的小花园",text:"你的小店让我想起从前。愿我们都有自己的小小天地。",main:3,accent:4,mainNeed:6,accentNeed:3,charm:"daisy",reward:300,rep:25,palette:[3,4,3,3,4,3,3,4,3,3,0,3]},{id:"violet",name:"自己的名字",customer:"花店小满",occasion:"为原创设计展定制",text:"展签上一定要写上你的名字。这是你的作品，你值得被看见。",main:5,accent:0,mainNeed:6,accentNeed:3,charm:"moon",reward:340,rep:30,palette:[5,0,5,5,0,5,5,0,5,5,4,5]},{id:"promise",name:"把日子串成光",customer:"奶奶",occasion:"给正在学着站稳的你",text:"给自己做一条吧。不是为了讨好谁，是为了记住你走过的路。",main:0,accent:4,mainNeed:6,accentNeed:3,charm:"heart",reward:420,rep:40,palette:[0,4,0,0,4,0,0,4,0,0,1,0]}]),e("CHAPTERS",[{title:"第一章 · 旧桌上的第一束光",subtitle:"失去父母之后，阿禾和奶奶要先守住自己的生活。",goal:"靠前两份委托，攒下独立经营的第一笔收入。"},{title:"第二章 · 留下自己的名字",subtitle:"叔婶的贬低没有停，抄袭和流言又找上了门。",goal:"留下设计过程，用真实订单和记录回应质疑。"},{title:"第三章 · 由我决定的明天",subtitle:"拒绝被控制的合作，也开始追问那份被侵占的遗产。",goal:"保住独立署名，整理资料，迈出正式求助的第一步。"}]),e("JOURNEY",[{title:"先挣到属于我们的第一笔钱",pressure:"叔婶占着父母留下的房产和存款，又说阿禾的手作不值钱。",goal:"采集珍珠与绿玉，完成林阿姨的雏菊手串。",result:"第一张订单收据，让阿禾看见靠手艺生活的可能。"},{title:"留下每一笔属于自己的收入",pressure:"婶婶要求小店交出收入，声称是在替阿禾保管。",goal:"完成小满的海风手串，建立自己的订单账。",result:"小满成为回头客，也提醒阿禾保存草图和定制记录。"},{title:"把被抹掉的名字写回来",pressure:"邻店抄走配色，婶婶又借机散布“阿禾才是模仿者”的话。",goal:"完成许老师的委托，留下从草图到成品的记录。",result:"许老师愿意为亲眼见过的创作过程作证。"},{title:"让真实客人的声音被听见",pressure:"叔叔上门催阿禾关店，邻店继续用低价和流言抢客。",goal:"完成林阿姨的花园纪念手串，用老客订单稳住口碑。",result:"定制记录和顾客反馈被整理成原创说明。"},{title:"机会不能以交出自己为代价",pressure:"采购方把展位与买断署名捆绑，叔叔还要求代管小店。",goal:"为小满完成署名参展作品，坚持独立经营。",result:"作品以“阿禾手作”署名，换取展位的苛刻合同没有被签下。"},{title:"第一次，为自己做一条手串",pressure:"叔婶仍拒绝说明遗产去向，独立开店没有让争议自动消失。",goal:"完成奶奶的心意委托，整理现有资料准备正式咨询。",result:"阿禾站稳了生活的第一步，遗产争议进入下一阶段。"},{title:"小店开着，故事继续",pressure:"遗产还没有追回，经营也会继续遇到难题。",goal:"翻阅手账、布置小店，或自由设计新的手串。",result:"下一篇：核查遗产资料，面对更大的合作与经营压力。"}]),e("STORIES",[{id:"old-table",chapter:0,summary:"失去父母的阿禾与奶奶相依为命。叔婶控制着遗产，她决定从一张旧桌子开始，靠手作挣自己的生活。",title:"他们说，你什么也做不成",lines:[["往事","阿禾幼年时，父母在一场车祸中离世。此后，是奶奶陪她长大。"],["往事","叔叔婶婶以代管为名，占着父母留下的房产和存款。祖孙几次追问，换来的都是推诿和羞辱。"],["婶婶","你们吃住哪样不要钱？那点遗产早花完了。就靠串这些珠子，你还想开店？"],["阿禾","那就请把账目给我们看。至于手串，我会自己试。"],["奶奶","妈妈留下的旧珠盒还在。先用这张桌子，我陪你把第一份委托做好。"],["阿禾","我想让奶奶过得安稳，也想自己决定往后的日子。先从今天开始。"]]},{id:"first-receipt",chapter:0,afterOrder:"daisy",summary:"第一份手串被认真珍惜。面对婶婶索要收入，阿禾保留订单收据，开始独立记账。",title:"第一张收据，我自己收着",evidence:{title:"第一张订单收据",text:"林阿姨的雏菊手串收据。它记录了阿禾独立挣得的第一笔收入；这是经营记录，不是遗产权属证明。"},lines:[["林阿姨","妈妈戴上后一直摸着那朵小花。谢谢你，认真听我讲她的故事。"],["婶婶","既然卖出去了，就把钱交来。你这么年轻，还是我们替你管着稳妥。"],["阿禾","这是我的订单收入，我自己记账。父母留下的钱，我们也还需要一份清楚的说明。"],["奶奶","别被她的话吓住。今天先把收据收好，给自己记上第一笔。"],["阿禾","原来我做的东西，真的有人珍惜。这张收据，我自己收着。"]]},{id:"stolen-design",chapter:0,afterOrder:"sea",summary:"第二份订单带来朋友，也带来抄袭风波。小满和阿禾一起保留原稿，准备回应流言。",title:"留下自己的名字",evidence:{title:"带日期的配珠草图",text:"海风手串的草图、试串照片和定制要求放在一起，形成可供核对的创作记录。"},lines:[["小满","海风手串我很喜欢。但邻店把你的图样换了名字，还说你才是模仿的人。"],["婶婶","我早说你撑不起店。被人找上门，别指望我们替你出头。"],["阿禾","小时候被人堵在路上嘲笑，我总是躲。这次我还是害怕，可我不能把自己的作品也让出去。"],["小满","我有当时讨论配色的消息。把你的草图和试串也放在一起，我们按时间说清楚。"],["阿禾","好。先完成许老师的委托，每一次修改也都记下来。"]]},{id:"design-record",chapter:1,afterOrder:"rose",summary:"许老师核对了创作过程。阿禾开始靠记录和可信的帮助保护作品。",title:"用作品说话",evidence:{title:"顾客确认的定制记录",text:"许老师确认了定制沟通和制作过程。记录让事实更清楚，也让阿禾学会在需要时求助。"},lines:[["许老师","你为学生做的手串很用心。草图到成品的过程，我也亲眼见过。你可以把我确认的记录放进说明里。"],["叔叔","别人说你抄，你就别做了。把店关了，省得丢家里的脸。"],["阿禾","我不会因为几句话就关店。我的作品有记录，客人的委托我也会完成。"],["许老师","把事实逐项公开，别跟着流言争吵。如果侵权继续，再寻求合适的专业帮助。"],["奶奶","今晚先吃顿热饭。你已经迈出一步了，不必一口气扛完。"]]},{id:"unfair-contract",chapter:1,afterOrder:"forest",summary:"回头客帮小店稳住口碑，新的采购方却要求买断署名。阿禾决定不拿独立经营换展位。",title:"更大的机会，更小的名字？",evidence:{title:"标出争议的合作草案",text:"草案中的买断署名、独家经营和结算条款被逐项标出。阿禾没有签署它，准备提出修改。"},lines:[["林阿姨","花园重新开张了，你的小店也要好好开下去。我会把真实的定制经历告诉朋友。"],["采购方","我们可以给你展位。但所有设计署我们品牌的名字，你以后也只能替我们供货。"],["叔叔","这么大的机会你还挑？经营权交给我管，这份合同我替你签。"],["阿禾","我的店和我的作品，由我决定。这份合同先不签，署名、独家和结算条款都要重新谈。"],["小满","我已经找到可以独立报名的市集。下一条参展作品，我们把你的名字写清楚。"]]},{id:"own-name",chapter:2,afterOrder:"violet",summary:"作品终于以自己的名字参展，叔婶却仍用遗产压她低头。阿禾开始整理现有材料寻求咨询。",title:"署名是我的，人生也是",evidence:{title:"阿禾手作的参展卡",text:"自己的名字终于留在展签上。它证明的是这一步经营成长；父母遗产的去向仍需要核查。"},lines:[["小满","展签写好了：设计与制作，阿禾手作。已经有人来问下一次定制了。"],["婶婶","翅膀硬了？再追问你爸妈那些钱，以后别来找我们。"],["阿禾","我不会交出店，也不会不再问。请把你们说代管过的资料和账目拿出来。"],["奶奶","家里还留着一些旧材料。我们先列清单，再去咨询该怎么核查，不能只听他们一句话。"],["阿禾","好。今天先为自己做一条手串，记住我有权决定自己的生活。"]]},{id:"first-independence",chapter:2,afterOrder:"promise",summary:"阿禾挣到了独立生活的底气，也整理好咨询清单。遗产尚未追回，她决定带着记录继续往前走。",title:"先站稳，再把属于我们的找回来",lines:[["奶奶","这条手串，是给一直没有放弃手作的你。不是替别人做，也不用证明给谁看。"],["阿禾","爸妈离开之后，我总觉得自己只能等别人决定。现在小店是我一点点做起来的。"],["奶奶","现有材料和要问的问题都写好了。下次咨询，我们一起去。"],["阿禾","遗产还没追回，那份合同也没谈成。但我有自己的收入，有记录，也知道可以向谁求助。"],["阿禾","明天继续开门。属于我们的生活，我会一步一步守住。"],["下一篇","遗产资料核查、供应商施压与新的委托，将在后续章节继续。本篇先记录阿禾独立经营的第一步。"]]},{id:"grandma-chair",chapter:0,furniture:"chair",summary:"添置软垫椅后，奶奶讲起阿禾小时候拆了又串的第一条手串。",title:"奶奶终于能坐得舒服一点",lines:[["奶奶","这把椅子坐着真暖和。你小时候串错一颗，能拆开重来好几遍。"],["阿禾","你那时从来没说我笨。我想让你以后都坐得舒服，不用陪我硬撑。"],["奶奶","你慢慢来。我陪你，是因为我喜欢看你做喜欢的事。"]]},{id:"keepsake-box",chapter:1,furniture:"desk",summary:"整理新工作台时，阿禾把母亲留下的珠盒与自己的原稿分格收好。",title:"旧珠盒，有了自己的抽屉",evidence:{title:"母亲留下的旧珠盒",text:"阿禾童年见过的珠盒，装着母亲留下的旧珠子。它是关于家人的记忆，不是突然解决遗产争议的秘密证据。"},lines:[["阿禾","妈妈的旧珠盒放这格，草图和收据放另一格。以后每件东西都有自己的位置。"],["奶奶","你小时候总趴在桌边看她挑珠子。现在，你也有自己的设计了。"],["阿禾","我想念他们。但接下来这间店，我要按自己的心意做。"]]},{id:"signed-display",chapter:2,furniture:"display",summary:"新展示柜摆好后，阿禾给作品留下署名和故事。",title:"柜子里的作品，都有名字",lines:[["小满","作品卡上除了配色，还能写委托的心意。客人看到的，就不只是价钱。"],["阿禾","每一件都写上阿禾手作，也记下客人的许可。我的作品值得被认真对待。"],["奶奶","柜子一点点摆满，日子也一点点有了自己的样子。"]]}]),e("FURNITURE",[{id:"chair",title:"奶奶的窗边椅",text:"让她陪伴的每个下午，都舒服一些。",names:["旧木椅","鼠尾草软垫椅","雾蓝扶手椅"],prices:[0,160,360],art:["chair-wood","chair-sage","chair-blue"]},{id:"display",title:"作品展示柜",text:"升级后解锁「作品署名」支线，让原创拥有自己的位置。",names:["旧陈列架","玻璃珠宝柜","花窗展示柜"],prices:[0,200,400],art:[]},{id:"desk",title:"阿禾的工作桌",text:"升级后解锁「母亲的旧珠盒」支线，把原稿和记忆收好。",names:["旧木桌","分格手作台","原创设计桌"],prices:[0,180,380],art:[]}]),e("CHARMS",{daisy:"雏菊",moon:"月牙",heart:"爱心"}),e("CLEAN_SPOTS",[{id:"box-left",kind:"clutter",name:"收走左边的旧纸箱",x:18,y:73},{id:"box-right",kind:"clutter",name:"收走右边的旧纸箱",x:82,y:75},{id:"papers",kind:"clutter",name:"收好散落的废纸",x:58,y:85},{id:"glass-1",kind:"glass",name:"擦净左上窗渍",x:44,y:23},{id:"glass-2",kind:"glass",name:"擦净右上窗渍",x:56,y:24},{id:"glass-3",kind:"glass",name:"擦净左下窗渍",x:44,y:37},{id:"glass-4",kind:"glass",name:"擦净右下窗渍",x:56,y:38},{id:"dust-1",kind:"dust",name:"扫净门边灰尘",x:12,y:88},{id:"dust-2",kind:"dust",name:"扫净椅边灰尘",x:35,y:82},{id:"dust-3",kind:"dust",name:"扫净柜边灰尘",x:70,y:89},{id:"dust-4",kind:"dust",name:"扫净墙边灰尘",x:90,y:86}]),e("REPAIRS",[{id:"wall",title:"修补墙面",result:"奶油色新墙面",price:60,text:"补好裂缝，刷上温暖的奶油色。",icon:"paint"},{id:"floor",title:"铺好地板",result:"蜂蜜色木地板",price:40,text:"换掉翘起的旧板，让奶奶走得更安心。",icon:"floor"},{id:"window",title:"修好窗户",result:"明亮花窗与窗帘",price:20,text:"换好破损玻璃，让阳光重新照进来。",icon:"window"}]);t._RF.pop()}}}));

